use std::{fs,path::Path};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/ready-solver246");let p=r.join("source/crates/zopro-core/src/solver/sparse_poseidon/tests.rs");let old=fs::read_to_string(&p).unwrap();fs::write(r.join("sparse-poseidon-tests-original.rs"),&old).unwrap();let anchor="        schedule: std::sync::OnceLock::new(),";assert_eq!(old.matches(anchor).count(),1);let new=old.replace(anchor,&format!("{anchor}\n        #[cfg(zopro_ready_solver)]\n        ready: std::sync::OnceLock::new(),"));fs::write(&p,new).unwrap();let mut pins:Value=serde_json::from_slice(&fs::read(r.join("build-pins.json")).unwrap()).unwrap();pins[p.display().to_string()]=json!(format!("{:x}",Sha256::digest(fs::read(&p).unwrap())));fs::write(r.join("build-pins-v3.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();let mut plan:Value=serde_json::from_slice(&fs::read(r.join("build-plan-v2.json")).unwrap()).unwrap();plan["source_pins"]=json!(r.join("build-pins-v3.json"));for step in plan["steps"].as_array_mut().unwrap(){if step["kind"]=="link-sdk"{step["artifacts"]=json!(r.join("build-v3/libraries/stdout.log"));}}fs::write(r.join("build-plan-v3.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Test-only Plan initializer includes private cache; pre-test compile failure retained");}
